            _nft,
            /* _virtualBaseTokenReserves */ uint128(1),
            /* _virtualNftReserves */ uint128(1),
            /* _changeFee */ uint56(0),
            /* _feeRate */ uint16(0),
            /* _merkleRoot */ bytes32(0),
            /* _useStolenNftOracle */ false,
            /* _payRoyalties */ false
