        // Keep domain wide but avoid zero-address for factory/royalty dependencies not relevant here
        // Allow _baseToken or _nft to be zero (it's admissible in original contract), so no assume on them.
        // Bound feeRate to allowed range to avoid immediate revert FeeRateTooHigh
        if (_feeRate > 6000) _feeRate = _feeRate % 5001; // keep within and not too tight

        bool ok;
        // Call initialize and capture whether it reverted or not. The correct contract should not revert for feeRate <=5000
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
